# -*- coding: utf-8 -*-
"""
Pool module for Part 1: Unit 2 Knowledge Organization, Information Processing & Retrieval (Q21 to Q40).
Provides 20 authentic, unique bilingual questions per paper across 48 papers.
"""

def make_question(q_id, sec_en, sec_hi, u_en, u_hi, q_en, q_hi, c_en, c_hi, w_en, w_hi, exp_en, exp_hi, ans_idx):
    opts_en = list(w_en)
    opts_hi = list(w_hi)
    opts_en.insert(ans_idx, c_en)
    opts_hi.insert(ans_idx, c_hi)
    ans_letter = chr(ord("A") + ans_idx)
    return {
        "id": q_id,
        "section_en": sec_en,
        "section_hi": sec_hi,
        "unit_en": u_en,
        "unit_hi": u_hi,
        "q_en": q_en,
        "q_hi": q_hi,
        "options_en": opts_en,
        "options_hi": opts_hi,
        "answer": ans_letter,
        "exp_en": exp_en,
        "exp_hi": exp_hi
    }

SEC_EN = "Part 1: Library & Information Science"
SEC_HI = "भाग 1: पुस्तकालय एवं सूचना विज्ञान"
U_EN = "Unit 2: Knowledge Organization, Information Processing and Retrieval"
